#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_node_only_ct(void) {
    // Setup: Build a linked list with at least two nodes.
    // We need the target node to NOT be the head, and we want to update only CT (non-zero),
    // while WT and TAT are zero (so those branches are skipped).
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial CT values are zero (as set by insert)
    node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(0, ptr->CT);
        ptr = ptr->next;
    }

    // Test: Update node with ID=2 (non-head) with CT=100, WT=0, TAT=0.
    // This triggers the path:
    // - ptr = *root
    // - head condition fails (ptr->ID != id)
    // - traverse loop runs until ptr->ID == id (node 2)
    // - ct != 0 is true -> update CT
    // - wt != 0 is false -> skip WT
    // - tat != 0 is false -> skip TAT
    update(&root, 2, 100, 0, 0);

    // Assertions: Verify only node 2's CT changed, others unchanged.
    ptr = root;
    while (ptr != NULL) {
        if (ptr->ID == 2) {
            TEST_ASSERT_EQUAL_INT(100, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);
            TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        } else {
            TEST_ASSERT_EQUAL_INT(0, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);
            TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        }
        ptr = ptr->next;
    }

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_node_only_ct);
    return UNITY_END();
}

